@Override
    public Function<Double, Double> calculate(LivingEntity entity, Temperature.Trait trait)
    {
        double insulationStrength = ConfigSettings.INSULATION_STRENGTH.get();

        return temp ->
        {
            double insulation = temp > 0
                                ? this.getNBT().getDouble("HeatInsulation")
                                : this.getNBT().getDouble("ColdInsulation");
            return CSMath.blend(temp, 0, insulation * insulationStrength, 0, 1);
        };
    }

@Override
    protected Function<Double, Double> calculate(LivingEntity entity, Temperature.Trait trait)
    {
        Level level = entity.level();
        if (level.dimensionType().hasCeiling() || !level.dimensionType().hasSkyLight()) return temp -> temp;

        double darkness = 1 - (level.getBrightness(LightLayer.SKY, BlockPos.containing(entity.getEyePosition())) / 15.0);
        darkness *= Math.max(0, WorldHelper.getTimeMultiplier(level));
        double overcast = level.getRainLevel(1);
        double shade = Math.max(darkness, overcast);

        double shadeAmount = CSMath.blend(0, ConfigSettings.SHADE_TEMP_OFFSET.get(), shade, 0, 1);

        return temp -> temp + shadeAmount;
    }

