@Override
    public Function<Double, Double> calculate(LivingEntity entity, Temperature.Trait trait)
    {
        double cold = this.getNBT().getDouble("cold");
        double heat = this.getNBT().getDouble("heat");
        return temp ->
        {
            double insulation = temp > 0 ? heat : cold;
            return temp * (insulation >= 0 ? Math.pow(0.1, insulation / 60) : -(insulation / 20) + 1);
        };
    }

@Override
    public Function<Double, Double> calculate(LivingEntity entity, Temperature.Trait trait)
    {
        if (ModConfig.seasons.whitelistedDimensions.contains(entity.level().dimension().location().toString()))
        {
            ISeasonState season = SeasonHelper.getSeasonState(entity.level());

            SeasonalTempData springTemps = ConfigSettings.SPRING_TEMPS.get();
            SeasonalTempData summerTemps = ConfigSettings.SUMMER_TEMPS.get();
            SeasonalTempData autumnTemps = ConfigSettings.AUTUMN_TEMPS.get();
            SeasonalTempData winterTemps = ConfigSettings.WINTER_TEMPS.get();

            Pair<Double, Double> startEndTemps = switch (season.getSubSeason())
            {
                case EARLY_AUTUMN -> Pair.of(autumnTemps.getStartTemp(),  autumnTemps.getMiddleTemp());
                case MID_AUTUMN   -> Pair.of(autumnTemps.getMiddleTemp(), autumnTemps.getEndTemp());
                case LATE_AUTUMN  -> Pair.of(autumnTemps.getEndTemp(),    winterTemps.getStartTemp());

                case EARLY_WINTER -> Pair.of(winterTemps.getStartTemp(),  winterTemps.getMiddleTemp());
                case MID_WINTER   -> Pair.of(winterTemps.getMiddleTemp(), winterTemps.getEndTemp());
                case LATE_WINTER  -> Pair.of(winterTemps.getEndTemp(),    springTemps.getStartTemp());

                case EARLY_SPRING -> Pair.of(springTemps.getStartTemp(),  springTemps.getMiddleTemp());
                case MID_SPRING   -> Pair.of(springTemps.getMiddleTemp(), springTemps.getEndTemp());
                case LATE_SPRING  -> Pair.of(springTemps.getEndTemp(),    summerTemps.getStartTemp());

                case EARLY_SUMMER -> Pair.of(summerTemps.getStartTemp(),  summerTemps.getMiddleTemp());
                case MID_SUMMER   -> Pair.of(summerTemps.getMiddleTemp(), summerTemps.getEndTemp());
                case LATE_SUMMER  -> Pair.of(summerTemps.getEndTemp(),    autumnTemps.getStartTemp());
            };
            double startValue = startEndTemps.getFirst();
            double endValue = startEndTemps.getSecond();

            return temp -> temp + (float) CSMath.blend(startValue, endValue, season.getDay() % (season.getSubSeasonDuration() / season.getDayDuration()), 0, 8);
        }

        return temp -> temp;
    }

@Override
    protected Function<Double, Double> calculate(LivingEntity entity, Temperature.Trait trait)
    {
        if (!entity.level().isClientSide())
        {
            BlockPos entityPos = WorldHelper.sublevelToWorld(entity.level(), entity.blockPosition());
            WeatherManagerServer weatherManager = ServerTickHandler.getWeatherManagerFor(entity.level().dimension());
            float windSpeed = weatherManager.getWindManager().getWindSpeedPositional(entityPos);

            WeatherObject weather = (WeatherObject) CompatManager.Weather2.getClosestStorm(entity.level(), entityPos);
            double stormTemp;
            // If there is a blizzard/sandstorm, apply the temperature and wind speed modifiers
            if (weather instanceof WeatherObjectParticleStorm storm)
            {
                double distance = storm.posGround.distanceTo(entity.position());

                if (storm.type == WeatherObjectParticleStorm.StormType.SANDSTORM)
                {   stormTemp = -CSMath.blend(0, storm.getIntensity() / 3, distance, storm.getSize(), 0);
                }
                else if (storm.type == WeatherObjectParticleStorm.StormType.SNOWSTORM)
                {   stormTemp = CSMath.blend(0, storm.getIntensity(), distance, storm.getSize(), 0);
                }
                else
                {   stormTemp = 0;
                }
            }
            else if (weather instanceof StormObject storm
            && storm.levelCurIntensityStage >= StormObject.STATE_FORMING)
            {
                double distance = storm.posGround.distanceTo(entity.position());
                stormTemp = CSMath.blend(0, storm.strength / 300, distance, storm.getSize(), 0);
            }
            else
            {   stormTemp = 0;
            }
            return temp -> temp - stormTemp - windSpeed / 5;
        }
        return temp -> temp;
    }

public static double convert(double value, Units from, Units to, boolean absolute)
    {
        return switch (from)
        {
            case C -> switch (to)
            {
                case C -> value;
                case F -> value * 1.8 + (absolute ? 32d : 0d);
                case MC -> value / 25d;
            };
            case F -> switch (to)
            {
                case C -> (value - (absolute ? 32d : 0d)) / 1.8;
                case F -> value;
                case MC -> (value - (absolute ? 32d : 0d)) / 45d;
            };
            case MC -> switch (to)
            {
                case C -> value * 25d;
                case F -> value * 45d + (absolute ? 32d : 0d);
                case MC -> value;
            };
        };
    }

