private boolean shouldFreeze(Level level, BlockPos pos, BlockState state)
    {
        if (this.getFluid().is(ModFluidTags.SLUSH))
        {
            FluidState slushState = level.getFluidState(pos);

            for (Direction direction : POSSIBLE_FLOW_DIRECTIONS)
            {
                BlockPos neighborPos = pos.relative(direction);
                FluidState neighborFluid = level.getFluidState(neighborPos);

                if (neighborFluid.is(FluidTags.WATER))
                {
                    if (direction == Direction.DOWN)
                    {
                        Block resultBlock = Blocks.SNOW_BLOCK;
                        level.setBlockAndUpdate(pos.below(), net.minecraftforge.event.ForgeEventFactory.fireFluidPlaceBlockEvent(level, pos.below(), pos, resultBlock.defaultBlockState()));
                        SlushFluid.fizz(level, pos);
                    }
                    else
                    {
                        Block resultBlock = slushState.isSource() ? Blocks.ICE : Blocks.SNOW_BLOCK;
                        level.setBlockAndUpdate(pos, net.minecraftforge.event.ForgeEventFactory.fireFluidPlaceBlockEvent(level, pos, pos, resultBlock.defaultBlockState()));
                        SlushFluid.fizz(level, pos);
                    }
                    return true;
                }
            }
        }
        return false;
    }

