public static Facing fromDirection(Direction direction)
        {
            return switch (direction)
            {
                case DOWN -> DOWN;
                case NORTH -> NORTH;
                case SOUTH -> SOUTH;
                case EAST -> EAST;
                case WEST -> WEST;
                default -> UP;
            };
        }

public Direction toDirection()
        {
            return switch (this)
            {
                case DOWN -> Direction.DOWN;
                case NORTH -> Direction.NORTH;
                case SOUTH -> Direction.SOUTH;
                case EAST -> Direction.EAST;
                case WEST -> Direction.WEST;
                default -> Direction.UP;
            };
        }

@Nullable
        public Direction.Axis getAxis()
        {   return this == BEND ? null : this.toDirection().getAxis();
        }

public Facing rotate(Rotation rotation)
        {
            return switch (rotation)
            {
                case CLOCKWISE_90 -> switch (this)
                {
                    case NORTH -> EAST;
                    case EAST -> SOUTH;
                    case SOUTH -> WEST;
                    case WEST -> NORTH;
                    default -> this;
                };
                case CLOCKWISE_180 -> switch (this)
                {
                    case NORTH -> SOUTH;
                    case SOUTH -> NORTH;
                    case EAST -> WEST;
                    case WEST -> EAST;
                    default -> this;
                };
                case COUNTERCLOCKWISE_90 -> switch (this)
                {
                    case NORTH -> WEST;
                    case WEST -> SOUTH;
                    case SOUTH -> EAST;
                    case EAST -> NORTH;
                    default -> this;
                };
                default -> this;
            };
        }

public Facing mirror(Mirror mirror)
        {
            return switch (mirror)
            {
                case FRONT_BACK -> switch (this)
                {
                    case NORTH -> SOUTH;
                    case SOUTH -> NORTH;
                    default -> this;
                };
                case LEFT_RIGHT -> switch (this)
                {
                    case EAST -> WEST;
                    case WEST -> EAST;
                    default -> this;
                };
                default -> this;
            };
        }

