public boolean matches(Map<Temperature.Trait, Double> temps)
        {
            for (TriggerHelper.TempCondition condition : conditions)
            {
                double value = temps.get(condition.trait());

                if (!condition.matches(value))
                    return false;
            }
            return true;
        }

