@SubscribeEvent
    public static void remapMissingItems(MissingMappingsEvent event)
    {
        if (event.getRegistry().getRegistryName().equals(ForgeRegistries.ITEMS.getRegistryName()))
        {
            for (MissingMappingsEvent.Mapping<Item> mapping : event.getAllMappings(ForgeRegistries.Keys.ITEMS))
            {
                ResourceLocation key = mapping.getKey();
                String namespace = key.getNamespace();
                String path = key.getPath();
                if (namespace.equals(ColdSweat.MOD_ID))
                {
                    switch (path)
                    {
                        case "goat_fur_cap" :   mapping.remap(ModItems.GOAT_FUR_HELMET); break;
                        case "goat_fur_parka" : mapping.remap(ModItems.GOAT_FUR_CHESTPLATE); break;
                        case "goat_fur_pants" : mapping.remap(ModItems.GOAT_FUR_LEGGINGS); break;

                        case "hoglin_headpiece" : mapping.remap(ModItems.HOGLIN_HELMET); break;
                        case "hoglin_tunic" :     mapping.remap(ModItems.HOGLIN_CHESTPLATE); break;
                        case "hoglin_trousers" :  mapping.remap(ModItems.HOGLIN_LEGGINGS); break;
                        case "hoglin_hooves" :    mapping.remap(ModItems.HOGLIN_BOOTS); break;

                        case "chameleon_scale_helmet" :     mapping.remap(ModItems.CHAMELEON_HELMET); break;
                        case "chameleon_scale_chestplate" : mapping.remap(ModItems.CHAMELEON_CHESTPLATE); break;
                        case "chameleon_scale_leggings" :   mapping.remap(ModItems.CHAMELEON_LEGGINGS); break;
                        case "chameleon_scale_boots" :      mapping.remap(ModItems.CHAMELEON_BOOTS); break;
                        default: break;
                    }
                }
            }
        }
    }

@SubscribeEvent
    public static synchronized void runScheduledTasks(TickEvent event)
    {
        if ((event instanceof TickEvent.ServerTickEvent || event instanceof TickEvent.ClientTickEvent) && event.phase == TickEvent.Phase.START)
        {
            List<QueueEntry> schedule = event.side.isClient() ? CLIENT_SCHEDULE : SERVER_SCHEDULE;

            // Iterate through all active tasks
            if (!schedule.isEmpty())
            {
                for (int i = 0; i < schedule.size(); i++)
                {
                    QueueEntry entry = schedule.get(i);
                    int ticks = entry.time;

                    // If the task is ready to run, run it and remove it from the schedule
                    if (ticks <= 0)
                    {
                        try
                        {   entry.task.run();
                        }
                        catch (Exception e)
                        {   ColdSweat.LOGGER.error("Error while running scheduled task", e);
                            throw e;
                        }
                        schedule.remove(i);
                        i--;
                    }
                    // Otherwise, decrement the task's tick count
                    else
                    {   entry.time = ticks - 1;
                    }
                }
            }
        }
    }

public static void scheduleServer(Runnable task, int delay)
    {   SERVER_SCHEDULE.add(new QueueEntry(task, delay));
    }

public static void scheduleClient(Runnable task, int delay)
    {   CLIENT_SCHEDULE.add(new QueueEntry(task, delay));
    }

public static void schedule(Runnable task, int delay)
    {   scheduleServer(task, delay);
        scheduleClient(task, delay);
    }

public QueueEntry(Runnable task, int time)
        {   this.task = task;
            this.time = time;
        }

