@Nullable
    public static BiomeTempData fromToml(List<?> entry, boolean isOffset, RegistryAccess registryAccess)
    {
        if (!(entry.size() == 2 && entry.get(1) instanceof String || entry.size() >= 3))
        {   ColdSweat.LOGGER.error("Error parsing biome config: not enough arguments");
            return null;
        }
        NegatableList<Either<TagKey<Biome>, OptionalHolder<Biome>>> biomes = ConfigHelper.parseRegistryItems(Registries.BIOME, registryAccess, (String) entry.get(0));
        if (biomes.isEmpty()) return null;

        Temperature.Units units = Temperature.Units.MC;
        double min = 0;
        double max = 0;
        Optional<Double> waterTemp = Optional.empty();
        Optional<Double> freezingPoint = Optional.empty();
        boolean isDisabled = false;
        // Disabled
        if (entry.get(1) instanceof String string && string.equals("disable"))
        {   isDisabled = true;
        }
        // Normal
        else
        {
            min = ((Number) entry.get(1)).doubleValue();
            max = ((Number) entry.get(2)).doubleValue();
            if (entry.size() >= 4) units = Temperature.Units.fromID(((String) entry.get(3)).toUpperCase());
            if (entry.size() >= 5) waterTemp = Optional.of(((Number) entry.get(4)).doubleValue());
            if (entry.size() >= 6) freezingPoint = Optional.of(((Number) entry.get(5)).doubleValue());
        }
        BiomeTempData result = new BiomeTempData(biomes, min, max, units, waterTemp, freezingPoint, isOffset, isDisabled);
        result.setConfigType(Type.TOML);
        return result;
    }

