public int getHeight(BlockPos checkPos, Level level)
        {
            return switch (anchor)
            {
                case CONSTANT -> depth;
                case WORLD_TOP -> level.getMaxBuildHeight() + depth;
                case WORLD_BOTTOM -> level.getMinBuildHeight() + depth;
                case GROUND_LEVEL -> WorldHelper.getHeight(checkPos, level, Heightmap.Types.MOTION_BLOCKING_NO_LEAVES) + depth;
            };
        }

public double getTemperature(double temperature)
        {
            return switch (this.temperature.type)
            {
                case STATIC ->
                {
                    if (this.temperature.strength == 0) yield temperature;
                    double convertedTemp = Temperature.convert(this.temperature.temperature, this.units, Temperature.Units.MC, true);
                    yield CSMath.blend(temperature, convertedTemp, this.temperature.strength, 0, 1);
                }
                case MIDPOINT ->
                {
                    if (this.temperature.strength == 0) yield temperature;
                    yield CSMath.blend(temperature, CSMath.average(ConfigSettings.MIN_TEMP.get(), ConfigSettings.MAX_TEMP.get()), this.temperature.strength, 0, 1);
                }
            };
        }

