public static boolean renderHealthBar(PoseStack matrixStack, final LivingEntity livingEntity) {
    return ChampionCapability.getCapability(livingEntity).map(champion -> {
      IChampion.Client clientChampion = champion.getClient();
      return clientChampion.getRank().map(rank -> {
        int num = rank.getA();
        Set<String> affixSet = clientChampion.getAffixes().stream().map(IAffix::getIdentifier)
          .collect(Collectors.toSet());

        if (num > 0 || affixSet.size() > 0) {
          Minecraft client = Minecraft.getInstance();
          int i = client.getWindow().getGuiScaledWidth();
          int k = i / 2 - 91;
          int j = 21;
          int xOffset = ClientChampionsConfig.hudXOffset;
          int yOffset = ClientChampionsConfig.hudYOffset;
          int color = rank.getB();
          float r = (float) ((color >> 16) & 0xFF) / 255f;
          float g = (float) ((color >> 8) & 0xFF) / 255f;
          float b = (float) ((color) & 0xFF) / 255f;

          RenderSystem.defaultBlendFunc();
          RenderSystem.setShaderColor(r, g, b, 1.0F);
          RenderSystem.enableBlend();
          RenderSystem.setShader(GameRenderer::getPositionTexShader);
          RenderSystem.setShaderTexture(0, GUI_BAR_TEXTURES);
          ChampionsOverlay.startX = xOffset + k;
          ChampionsOverlay.startY = yOffset + 1;

          GuiComponent.blit(matrixStack, xOffset + k, yOffset + j, 0, 60, 182, 5, 256, 256);
          int healthOffset =
            (int) ((livingEntity.getHealth() / livingEntity.getMaxHealth()) * 183.0F);

          if (healthOffset > 0) {
            GuiComponent.blit(matrixStack, xOffset + k, yOffset + j, 0, 65, healthOffset, 5, 256,
              256);
          }

          RenderSystem.setShaderTexture(0, GUI_STAR);

          if (num <= 18) {
            int startStarsX = xOffset + i / 2 - 5 - 5 * (num - 1);

            for (int tier = 0; tier < num; tier++) {
              GuiComponent.blit(matrixStack, startStarsX, yOffset + 1, 0, 0, 9, 9, 9, 9);
              startStarsX += 10;
            }
          } else {
            int startStarsX = xOffset + i / 2 - 5;
            String count = "x" + num;
            GuiComponent.blit(matrixStack, startStarsX - client.font.width(count) / 2,
              yOffset + 1, 0, 0, 9, 9, 9, 9);
            client.font.drawShadow(matrixStack, count,
              startStarsX + 10 - client.font.width(count) / 2.0F, yOffset + 2,
              16777215);
          }
          Component customName = livingEntity.getCustomName();
          String name;

          if (customName == null) {
            name = new TranslatableComponent("rank.champions.title." + num).getString();
            name += " " + livingEntity.getName().getString();
          } else {
            name = customName.getString();
          }
          client.font.drawShadow(matrixStack, name,
            xOffset + (float) (i / 2 - client.font.width(name) / 2),
            yOffset + (float) (j - 9), color);
          RenderSystem.setShaderColor(1.0F, 1.0F, 1.0F, 1.0F);
          StringBuilder builder = new StringBuilder();

          for (String affix : affixSet) {
            builder.append(
              new TranslatableComponent("affix." + Champions.MODID + "." + affix).getString());
            builder.append(" ");
          }
          String affixes = builder.toString().trim();
          client.font.drawShadow(matrixStack, affixes,
            xOffset + (float) (i / 2 - client.font.width(affixes) / 2),
            yOffset + (float) (j + 6), 16777215);
          RenderSystem.disableBlend();
          return true;
        }
        return false;
      }).orElse(false);
    }).orElse(false);
  }

public static Optional<LivingEntity> getMouseOverChampion(Minecraft mc, float partialTicks) {
    Entity entity = mc.getCameraEntity();

    if (entity != null) {

      if (mc.level != null) {
        mc.getProfiler().push("mouse_champion");
        double d0 = ClientChampionsConfig.hudRange;
        HitResult rayTraceResult = entity.pick(d0, partialTicks, false);
        Vec3 vec3d = entity.getEyePosition(partialTicks);
        double d1 = rayTraceResult.getLocation().distanceToSqr(vec3d);
        Vec3 vec3d1 = entity.getViewVector(1.0F);
        Vec3 vec3d2 = vec3d.add(vec3d1.x * d0, vec3d1.y * d0, vec3d1.z * d0);
        AABB axisalignedbb =
            entity.getBoundingBox().expandTowards(vec3d1.scale(d0)).inflate(1.0D, 1.0D, 1.0D);
        EntityHitResult entityraytraceresult =
            ProjectileUtil.getEntityHitResult(entity, vec3d, vec3d2, axisalignedbb,
                (e) -> !e.isSpectator() && e.isPickable(), d1);

        if (entityraytraceresult != null) {
          Entity entity1 = entityraytraceresult.getEntity();
          return ChampionCapability.getCapability(entity1).map(IChampion::getLivingEntity);
        }
        mc.getProfiler().pop();
      }
    }
    return Optional.empty();
  }

@SubscribeEvent
  public void onLivingXpDrop(LivingExperienceDropEvent evt) {
    LivingEntity livingEntity = evt.getEntityLiving();
    ChampionCapability.getCapability(livingEntity)
      .ifPresent(champion -> champion.getServer().getRank().ifPresent(rank -> {
        int growth = rank.getGrowthFactor();

        if (growth > 0) {
          evt.setDroppedExperience(
            (growth * ChampionsConfig.experienceGrowth * evt.getOriginalExperience() +
              evt.getDroppedExperience()));
        }
      }));
  }

@SubscribeEvent
  public void onExplosion(ExplosionEvent.Start evt) {
    Explosion explosion = evt.getExplosion();
    Entity entity = explosion.getExploder();

    if (entity != null && !entity.getLevel().isClientSide()) {
      ChampionCapability.getCapability(entity)
        .ifPresent(champion -> champion.getServer().getRank().ifPresent(rank -> {
          int growth = rank.getGrowthFactor();

          if (growth > 0) {
            explosion.radius += ChampionsConfig.explosionGrowth * growth;
          }
        }));
    }
  }

@SubscribeEvent
  public void onLivingJoinWorld(EntityJoinWorldEvent evt) {
    Entity entity = evt.getEntity();

    if (!entity.getLevel().isClientSide()) {
      ChampionCapability.getCapability(entity).ifPresent(champion -> {
        IChampion.Server serverChampion = champion.getServer();
        Optional<Rank> maybeRank = serverChampion.getRank();

        if (maybeRank.isEmpty()) {
          ChampionBuilder.spawn(champion);
        }
        serverChampion.getAffixes().forEach(affix -> affix.onSpawn(champion));
        serverChampion.getRank().ifPresent(rank -> {
          List<Tuple<MobEffect, Integer>> effects = rank.getEffects();
          effects.forEach(effectPair -> champion.getLivingEntity()
            .addEffect(new MobEffectInstance(effectPair.getA(), 200, effectPair.getB())));
        });
      });
    }
  }

@SubscribeEvent
  public void onLivingUpdate(LivingUpdateEvent evt) {
    LivingEntity livingEntity = evt.getEntityLiving();

    if (livingEntity.getLevel().isClientSide()) {
      ChampionCapability.getCapability(livingEntity).ifPresent(champion -> {
        IChampion.Client clientChampion = champion.getClient();
        clientChampion.getAffixes().forEach(affix -> affix.onClientUpdate(champion));
        clientChampion.getRank().ifPresent(rank -> {
          if (ChampionsConfig.showParticles && rank.getA() > 0) {
            int color = rank.getB();
            float r = (float) ((color >> 16) & 0xFF) / 255f;
            float g = (float) ((color >> 8) & 0xFF) / 255f;
            float b = (float) ((color) & 0xFF) / 255f;

            livingEntity.getLevel().addParticle(ChampionsRegistry.RANK,
              livingEntity.position().x + (livingEntity.getRandom().nextDouble() - 0.5D) *
                (double) livingEntity.getBbWidth(), livingEntity.position().y +
                livingEntity.getRandom().nextDouble() * livingEntity.getBbHeight(),
              livingEntity.position().z + (livingEntity.getRandom().nextDouble() - 0.5D) *
                (double) livingEntity.getBbWidth(), r, g, b);
          }
        });
      });
    } else if (livingEntity.tickCount % 10 == 0) {
      ChampionCapability.getCapability(livingEntity).ifPresent(champion -> {
        IChampion.Server serverChampion = champion.getServer();
        serverChampion.getAffixes().forEach(affix -> affix.onServerUpdate(champion));
        serverChampion.getRank().ifPresent(rank -> {
          if (livingEntity.tickCount % 4 == 0) {
            List<Tuple<MobEffect, Integer>> effects = rank.getEffects();
            effects.forEach(effectPair -> livingEntity.addEffect(
              new MobEffectInstance(effectPair.getA(), 100, effectPair.getB())));
          }
        });
      });
    }
  }

@SubscribeEvent
  public void onLivingAttack(LivingAttackEvent evt) {
    LivingEntity livingEntity = evt.getEntityLiving();

    if (livingEntity.getLevel().isClientSide()) {
      return;
    }
    ChampionCapability.getCapability(livingEntity).ifPresent(champion -> {
      IChampion.Server serverChampion = champion.getServer();
      serverChampion.getAffixes().forEach(affix -> {

        if (!affix.onAttacked(champion, evt.getSource(), evt.getAmount())) {
          evt.setCanceled(true);
        }
      });
    });

    if (evt.isCanceled()) {
      return;
    }
    Entity source = evt.getSource().getDirectEntity();
    ChampionCapability.getCapability(source).ifPresent(champion -> {
      IChampion.Server serverChampion = champion.getServer();
      serverChampion.getAffixes().forEach(affix -> {

        if (!affix.onAttack(champion, evt.getEntityLiving(), evt.getSource(), evt.getAmount())) {
          evt.setCanceled(true);
        }
      });
    });
  }

