public AdaptableAffix() {
    super("adaptable", AffixCategory.DEFENSE);
  }

@Override
  public float onHurt(IChampion champion, DamageSource source, float amount, float newAmount) {
    String type = source.getMsgId();
    DamageData damageData = AffixData.getData(champion, this.getIdentifier(), DamageData.class);

    if (damageData.name.equalsIgnoreCase(type)) {
      newAmount -= amount * ChampionsConfig.adaptableDamageReductionIncrement * damageData.count;
      damageData.count++;
    } else {
      damageData.name = type;
      damageData.count = 0;
    }
    damageData.saveData();
    return Math.max(amount * (float) (1.0f - ChampionsConfig.adaptableMaxDamageReduction),
        newAmount);
  }

@Override
    public void readFromNBT(CompoundTag tag) {
      name = tag.getString("name");
      count = tag.getInt("count");
    }

@Override
    public CompoundTag writeToNBT() {
      CompoundTag compound = new CompoundTag();
      compound.putString("name", name);
      compound.putInt("count", count);
      return compound;
    }

public ArcticAffix() {
    super("arctic", AffixCategory.CC);
  }

@Override
  public List<Tuple<Integer, Goal>> getGoals(IChampion champion) {
    return Collections.singletonList(
        new Tuple<>(0, new AttackGoal((Mob) champion.getLivingEntity())));
  }

public AttackGoal(Mob mobEntity) {
      this.mobEntity = mobEntity;
    }

@Override
    public boolean canUse() {
      LivingEntity livingentity = this.mobEntity.getTarget();

      if (livingentity != null && livingentity.isAlive()) {
        return BasicAffix.canTarget(this.mobEntity, livingentity, true)
            && this.mobEntity.getLevel().getDifficulty() != Difficulty.PEACEFUL;
      } else {
        return false;
      }
    }

@Override
    public void start() {
      this.attackTime = ChampionsConfig.arcticAttackInterval * 20;
    }

@Override
    public void tick() {
      if (this.mobEntity.getLevel().getDifficulty() != Difficulty.PEACEFUL) {
        --this.attackTime;
        LivingEntity livingentity = this.mobEntity.getTarget();

        if (livingentity != null) {
          this.mobEntity.getLookControl().setLookAt(livingentity, 180.0F, 180.0F);
          double sqrDistance = this.mobEntity.distanceToSqr(livingentity);

          if (sqrDistance < 400.0D) {
            if (this.attackTime <= 0) {
              this.attackTime = ChampionsConfig.arcticAttackInterval * 20 +
                  this.mobEntity.getRandom().nextInt(10) * 20 / 2;
              this.mobEntity.level.addFreshEntity(
                  new ArcticBulletEntity(this.mobEntity.getLevel(), this.mobEntity, livingentity,
                      this.mobEntity.getDirection().getAxis()));
              this.mobEntity.playSound(SoundEvents.SHULKER_SHOOT,
                  2.0F, (this.mobEntity.getRandom().nextFloat() -
                      this.mobEntity.getRandom().nextFloat()) * 0.2F + 1.0F);
            }
          } else {
            this.mobEntity.setTarget(null);
          }
        }
        super.tick();
      }
    }

